    if (cu.ref && !cu.refPaid && state.users[cu.ref]) { cu.refPaid = true; const inv = state.users[cu.ref]; inv.points = (inv.points || 0) + 5000; await send(Number(cu.ref), L[inv.lang || 'ru'].friendBonus(5000)); }
