  if (c === '/sale' && a.length >= 2 && prod(a[0])) { const p = prod(a[0]); setOver(+a[0], { old: p.old && p.old > p.price ? p.old : p.price, price: n(a[1]) }); return send(chat, `🏷 Акция: ${money(n(a[1]), 'ru')}`); }
